//! Boot configuration, the install channel, and every hardcoded URL.
//!
//! All URLs live here so changing the hostnames later is a one-file edit.
//! The channel is here rather than in `paths` because it is pure env parsing
//! that both the filesystem layout and the default ports derive from; `paths`
//! consumes `Channel` and must not re-derive it.

use std::cmp::Ordering;
use std::fmt;

use crate::error::{validation, Result};

pub const CORE_VERSION: &str = "0.1.15";

// The Ed25519 trust root, generated by `build.rs` from the single committed
// `signing-keys.json` the release pipeline writes. Included rather than written
// here so the release step's write is what the binary compiles against; see
// `emit_signing_key` in `build.rs` for what the four hardcoded copies cost.
include!(concat!(env!("OUT_DIR"), "/signing_key.rs"));

/// Two-host layout.
///
/// `WEBSITE_BASE_URL` is the landing page (Cloudflare Worker / Astro static
/// assets). Nothing release-related lives there; the core runtime does not
/// consume it.
pub const WEBSITE_BASE_URL: &str = "https://loca.rzkyif.com";

const DEFAULT_STORAGE_BASE_URL: &str = "https://get.loca.rzkyif.com";
const DEFAULT_HF_BASE_URL: &str = "https://huggingface.co";

/// Default HTTP bind host. Override via `LOCA_CORE_HOST`.
pub const DEFAULT_HOST: &str = "127.0.0.1";
/// Stable's core port. Other channels offset from it; see [`Channel::port_offset`].
pub const DEFAULT_PORT: u16 = 7800;

/// The install channel, selecting the `~/.loca/<channel>/` subtree for all
/// per-channel state and offsetting the default ports so two channels can run
/// at once.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Channel {
    #[default]
    Stable,
    Dev,
    Latest,
}

impl Channel {
    /// From `LOCA_CHANNEL`, defaulting to stable. An unknown value is an error
    /// rather than a silent fallback, so a typo cannot mis-isolate data.
    pub fn from_env() -> Result<Self> {
        let raw = std::env::var("LOCA_CHANNEL").unwrap_or_default();
        Self::parse(raw.trim())
    }

    pub fn parse(raw: &str) -> Result<Self> {
        match raw {
            "" | "stable" => Ok(Channel::Stable),
            "dev" => Ok(Channel::Dev),
            "latest" => Ok(Channel::Latest),
            other => Err(validation(format!(
                "invalid LOCA_CHANNEL: {other} (expected one of stable, dev, latest)"
            ))),
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Channel::Stable => "stable",
            Channel::Dev => "dev",
            Channel::Latest => "latest",
        }
    }

    /// Suffix namespacing per-channel resources (binary filenames, keychain
    /// service names, OS service labels) away from stable. Stable gets the bare
    /// name. Mirrors the client's `channel.rs`.
    pub fn suffix(self) -> &'static str {
        match self {
            Channel::Stable => "",
            Channel::Dev => "-dev",
            Channel::Latest => "-latest",
        }
    }

    /// On-disk filename for one of Loca's own binaries, namespaced per channel
    /// so a latest install's `loca-core-latest` never collides with stable's
    /// `loca-core`. The `.exe` suffix on Windows is the caller's to add.
    /// Upstream third-party binaries keep their original names: they are
    /// isolated by the per-channel bin dir, and renaming a third-party archive
    /// buys nothing.
    pub fn bin_name(self, base: &str) -> String {
        format!("{base}{}", self.suffix())
    }

    /// [`Self::bin_name`] with the platform's executable suffix: the actual
    /// filename of one of Loca's own binaries on disk.
    ///
    /// Mirrors the oracle's `coreBinaryName` (`binaries/versions.ts:39`), which
    /// is `channelBinName(base) + platformExe()`. Both halves matter and both
    /// are easy to drop: without the channel suffix a `latest` install rolls
    /// back over stable's binary, and without `.exe` every Windows path built
    /// from this names a file that does not exist.
    pub fn core_binary_name(self, base: &str) -> String {
        with_exe(self.bin_name(base), platform_exe())
    }

    /// Offset applied to every default service port. An explicit value in
    /// settings.json still wins; only the default moves.
    pub fn port_offset(self) -> u16 {
        match self {
            Channel::Stable => 0,
            Channel::Latest => 10,
            Channel::Dev => 20,
        }
    }

    pub fn core_port(self) -> u16 {
        DEFAULT_PORT + self.port_offset()
    }

    /// Manifests live under a per-channel path segment so latest/dev publish and
    /// fetch their own signed manifests without touching stable's. Stable stays
    /// bare; dev and latest nest.
    fn manifest_dir(self) -> String {
        match self {
            Channel::Stable => "manifests".to_string(),
            other => format!("manifests/{}", other.as_str()),
        }
    }
}

impl fmt::Display for Channel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Everything resolved at boot from the environment.
#[derive(Debug, Clone)]
pub struct Config {
    pub channel: Channel,
    pub host: String,
    pub port: u16,
    pub version: &'static str,
    /// The release-artifact host. Overridable via `LOCA_STORAGE_BASE_URL` so the
    /// E2E harness can point catalog / manifest fetches at a local mock without
    /// touching the real R2 bucket. Production leaves it unset.
    pub storage_base_url: String,
    /// The HuggingFace host model-file downloads resolve against. Overridable
    /// via `LOCA_HF_BASE_URL` for the same test-isolation reason.
    pub hf_base_url: String,
}

impl Config {
    pub fn from_env() -> Result<Self> {
        let channel = Channel::from_env()?;
        let port = match std::env::var("LOCA_CORE_PORT") {
            Ok(raw) => raw
                .trim()
                .parse::<u16>()
                .ok()
                .filter(|p| *p > 0)
                .ok_or_else(|| validation(format!("invalid LOCA_CORE_PORT: {raw}")))?,
            Err(_) => channel.core_port(),
        };
        Ok(Self {
            channel,
            host: std::env::var("LOCA_CORE_HOST").unwrap_or_else(|_| DEFAULT_HOST.to_string()),
            port,
            version: CORE_VERSION,
            storage_base_url: std::env::var("LOCA_STORAGE_BASE_URL")
                .unwrap_or_else(|_| DEFAULT_STORAGE_BASE_URL.to_string()),
            hf_base_url: std::env::var("LOCA_HF_BASE_URL")
                .unwrap_or_else(|_| DEFAULT_HF_BASE_URL.to_string()),
        })
    }

    pub fn core_manifest_url(&self) -> String {
        self.manifest_url("core.json")
    }

    pub fn binary_manifest_url(&self) -> String {
        self.manifest_url("binaries.json")
    }

    /// Signed manifest for the CDN-distributed built-in extension.
    pub fn builtin_extension_manifest_url(&self) -> String {
        self.manifest_url("extension.json")
    }

    /// Signed model catalog: hand-authored in `@loca/model-catalog`, compiled
    /// and published by `deno task release`. The core fetches and verifies it,
    /// then runs the on-device fit engine against it.
    pub fn models_catalog_url(&self) -> String {
        self.manifest_url("catalog.json")
    }

    /// Schemas (`loca-v1.json`) are channel-independent: one published copy.
    pub fn schemas_base_url(&self) -> String {
        format!("{}/schemas", self.storage_base_url)
    }

    fn manifest_url(&self, file: &str) -> String {
        format!(
            "{}/{}/{file}",
            self.storage_base_url,
            self.channel.manifest_dir()
        )
    }
}

/// Compare two semver-ish versions, tolerating a leading `v` and missing parts.
///
/// Numeric segment by segment, so `1.10.0` is NEWER than `1.9.0`; a string
/// comparison gets that backwards, which is the whole reason this exists. A
/// non-numeric segment (a `-rc1` suffix, a date tag) compares as 0 rather than
/// erroring, because every caller is deciding whether to accept a SIGNED
/// document and refusing to answer would turn an unparseable version into a
/// hard failure of something otherwise valid.
///
/// **Here rather than beside its callers because it is a correctness control**
/// (D-049, D-053). It is what the binary manifest's replay refusal rests on, and
/// D13 needs the same comparison for `core.json`. A validly-signed OLDER
/// manifest is still validly signed, so this ordering is the only thing between
/// a replayed release and a rollback to a fixed vulnerability. Two comparators
/// that disagree about `1.10.0` versus `1.9.0` make that rollback succeed
/// silently, and a naive string compare gets exactly that pair wrong.
pub fn compare_semver(left: &str, right: &str) -> Ordering {
    let left = version_parts(left);
    let right = version_parts(right);
    for index in 0..left.len().max(right.len()) {
        let a = left.get(index).copied().unwrap_or(0);
        let b = right.get(index).copied().unwrap_or(0);
        match a.cmp(&b) {
            Ordering::Equal => continue,
            other => return other,
        }
    }
    Ordering::Equal
}

fn version_parts(version: &str) -> Vec<u64> {
    version
        .trim()
        .trim_start_matches('v')
        .split('.')
        .map(|segment| {
            let digits: String = segment.chars().take_while(char::is_ascii_digit).collect();
            digits.parse().unwrap_or(0)
        })
        .collect()
}

/// The Rust target triple of the running host, in the form the release assets
/// are named with (`deno-aarch64-apple-darwin.zip`).
///
/// Built from `cfg!` rather than read from an env var so it describes the binary
/// that is RUNNING, which is the thing that has to match the asset. Returns one
/// of: `aarch64-apple-darwin`, `x86_64-apple-darwin`, `aarch64-pc-windows-msvc`,
/// `x86_64-pc-windows-msvc`, `aarch64-unknown-linux-gnu`,
/// `x86_64-unknown-linux-gnu`.
///
/// Hoisted for the same reason as [`compare_semver`]: D7 names a download asset
/// with it and D13 names an update asset with it, and two private copies is how
/// one of them ends up asking for a file that was never published.
/// The composition rule behind [`Channel::core_binary_name`], with the suffix
/// passed in.
///
/// Split out ONLY so it can be tested with `.exe` on a machine that is not
/// Windows. Inlined, the `.exe` half is untestable on every host the fleet
/// actually runs on: `platform_exe()` is empty there, so deleting the
/// concatenation changes nothing and any test of it passes either way. That is
/// a test that cannot fail (D-050), and the first draft of this one was exactly
/// that before the mutation was staged against it.
fn with_exe(name: String, exe: &str) -> String {
    format!("{name}{exe}")
}

/// The platform's executable suffix: `.exe` on Windows, empty elsewhere.
///
/// Here rather than beside a caller because three of them want it (D13's swap
/// and rollback, the helper-binary boot check, and the installer) and a fourth
/// copy is how one of them ends up wrong on exactly one platform nobody is
/// testing on. Mirrors `platformExe` (`binaries/versions.ts:15`).
pub fn platform_exe() -> &'static str {
    if cfg!(target_os = "windows") {
        ".exe"
    } else {
        ""
    }
}

pub fn host_triple() -> &'static str {
    match (
        cfg!(target_arch = "aarch64"),
        cfg!(target_os = "macos"),
        cfg!(target_os = "windows"),
    ) {
        (true, true, _) => "aarch64-apple-darwin",
        (false, true, _) => "x86_64-apple-darwin",
        (true, _, true) => "aarch64-pc-windows-msvc",
        (false, _, true) => "x86_64-pc-windows-msvc",
        (true, _, _) => "aarch64-unknown-linux-gnu",
        (false, _, _) => "x86_64-unknown-linux-gnu",
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used)]
mod tests {
    #[test]
    fn the_baked_trust_root_is_a_usable_ed25519_key() {
        // Everything the core verifies (the model catalog, `binaries.json`,
        // `core.json` for self-update, and the seeded built-in extension) runs
        // through this one key, and each of those failures reads as "the server
        // sent something forged" rather than "the release wrote a bad key".
        //
        // The key now arrives from `signing-keys.json` via `build.rs`, so it is
        // whatever the release pipeline last wrote. This asserts the property
        // that makes it usable at all: it decodes and lands on the curve. The
        // build script's own length and alphabet checks catch the coarse
        // breakages earlier; this catches a well-formed 32 bytes that is not a
        // valid point, which only the curve arithmetic can tell.
        //
        // Deliberately NOT asserting a specific key value: that would restate
        // the file the build reads and would have to be edited on every
        // rotation, which is precisely the four-hardcoded-copies problem the
        // build step removed.
        let decoded = crate::models::canonical::decode_verifying_key(super::SIGNING_PUBLIC_KEY);
        assert!(
            decoded.is_ok(),
            "the baked signing key is not a usable Ed25519 verifying key, so every signature \
             check in the core will fail as forged: {decoded:?}",
        );
    }

    #[test]
    fn the_core_binary_name_carries_both_the_channel_and_the_exe_suffix() {
        // Two independent halves, and dropping either is silent on the platform
        // the author is using. Without the channel suffix a `latest` install
        // swaps over stable's binary; without `.exe` every Windows path built
        // from this names a file that does not exist. Asserted against
        // `platform_exe()` rather than a literal so the test states the rule on
        // both platforms instead of passing on one.
        // The channel half, observable on every host.
        assert_eq!(Channel::Stable.bin_name("loca-core"), "loca-core");
        assert_eq!(Channel::Dev.bin_name("loca-core"), "loca-core-dev");
        assert_eq!(Channel::Latest.bin_name("loca-core"), "loca-core-latest");

        // The exe half, through the seam, so BOTH platforms are asserted here
        // rather than one of them being asserted on Windows CI and nowhere else.
        assert_eq!(
            with_exe("loca-core-dev".to_string(), ".exe"),
            "loca-core-dev.exe"
        );
        assert_eq!(with_exe("loca-core-dev".to_string(), ""), "loca-core-dev");

        // And the composition actually uses both, on whatever host this is.
        assert_eq!(
            Channel::Latest.core_binary_name("loca-core"),
            with_exe(Channel::Latest.bin_name("loca-core"), platform_exe())
        );
    }

    #[test]
    fn platform_exe_is_dot_exe_only_on_windows() {
        assert_eq!(
            platform_exe(),
            if cfg!(target_os = "windows") {
                ".exe"
            } else {
                ""
            }
        );
    }

    use super::*;

    #[test]
    fn channel_parses_and_defaults_to_stable() {
        assert_eq!(Channel::parse("").unwrap(), Channel::Stable);
        assert_eq!(Channel::parse("stable").unwrap(), Channel::Stable);
        assert_eq!(Channel::parse("dev").unwrap(), Channel::Dev);
        assert_eq!(Channel::parse("latest").unwrap(), Channel::Latest);
        assert!(Channel::parse("Stable").is_err());
        assert!(Channel::parse("nightly").is_err());
    }

    #[test]
    fn ports_and_suffixes_match_the_channel_tables() {
        assert_eq!(Channel::Stable.core_port(), 7800);
        assert_eq!(Channel::Latest.core_port(), 7810);
        assert_eq!(Channel::Dev.core_port(), 7820);
        assert_eq!(Channel::Stable.suffix(), "");
        assert_eq!(Channel::Dev.suffix(), "-dev");
        assert_eq!(Channel::Latest.suffix(), "-latest");
    }

    #[test]
    fn bin_names_are_namespaced_per_channel() {
        assert_eq!(Channel::Stable.bin_name("loca-core"), "loca-core");
        assert_eq!(Channel::Latest.bin_name("loca-core"), "loca-core-latest");
        assert_eq!(
            Channel::Latest.bin_name("loca-core-updater"),
            "loca-core-updater-latest"
        );
        assert_eq!(Channel::Dev.bin_name("loca-core"), "loca-core-dev");
    }

    #[test]
    fn stable_manifests_stay_bare_and_others_nest() {
        let stable = Config {
            channel: Channel::Stable,
            host: DEFAULT_HOST.into(),
            port: 7800,
            version: CORE_VERSION,
            storage_base_url: DEFAULT_STORAGE_BASE_URL.into(),
            hf_base_url: DEFAULT_HF_BASE_URL.into(),
        };
        assert_eq!(
            stable.core_manifest_url(),
            "https://get.loca.rzkyif.com/manifests/core.json"
        );
        let dev = Config {
            channel: Channel::Dev,
            ..stable.clone()
        };
        assert_eq!(
            dev.models_catalog_url(),
            "https://get.loca.rzkyif.com/manifests/dev/catalog.json"
        );
        assert_eq!(
            dev.schemas_base_url(),
            "https://get.loca.rzkyif.com/schemas"
        );
    }

    #[test]
    fn a_numeric_segment_beats_a_lexical_comparison() {
        // The defect this exists to prevent: "1.10.0" < "1.9.0" as strings.
        assert_eq!(compare_semver("1.10.0", "1.9.0"), Ordering::Greater);
        assert_eq!(compare_semver("1.9.0", "1.10.0"), Ordering::Less);
    }

    #[test]
    fn a_leading_v_is_ignored_on_either_side() {
        assert_eq!(compare_semver("v2.8.2", "2.8.2"), Ordering::Equal);
        assert_eq!(compare_semver("v2.9.0", "2.8.2"), Ordering::Greater);
    }

    #[test]
    fn a_missing_segment_reads_as_zero() {
        assert_eq!(compare_semver("1.2", "1.2.0"), Ordering::Equal);
        assert_eq!(compare_semver("1.2.1", "1.2"), Ordering::Greater);
    }

    #[test]
    fn a_non_numeric_suffix_does_not_make_the_comparison_fail() {
        assert_eq!(compare_semver("1.2.3-rc1", "1.2.3"), Ordering::Equal);
        assert_eq!(compare_semver("1.3.0-rc1", "1.2.3"), Ordering::Greater);
    }

    #[test]
    fn the_host_triple_names_this_build_rather_than_a_default() {
        let triple = host_triple();
        assert!(triple.contains(if cfg!(target_arch = "aarch64") {
            "aarch64"
        } else {
            "x86_64"
        }));
        if cfg!(target_os = "macos") {
            assert!(triple.ends_with("apple-darwin"), "{triple}");
        }
    }
}
